const express=require('express');
const {getPool,sql}=require('../../config/db');
const audit=require('../../services/audit');
const router=express.Router();
function has(req,p){return req.user.permissions.includes(p)||req.user.permissions.includes('ADMIN_TOTAL')}
router.post('/compras/confirmar',async(req,res,next)=>{try{if(!has(req,'COMPRAS_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();const detalles=req.body.detalles||[];if(!req.body.ProveedorId||!detalles.length)return res.status(400).json({ok:false,message:'Proveedor y al menos un producto son obligatorios.'});for(const d of detalles){const vr=await p.request().input('prov',sql.Int,req.body.ProveedorId).input('prod',sql.Int,d.ProductoId).query(`SELECT TOP 1 p.ProductoId,COALESCE(pp.CostoReferencia,p.PrecioCompra) PrecioCompra,p.PorcentajeImpuesto FROM Productos p JOIN ProductoProveedores pp ON pp.ProductoId=p.ProductoId AND pp.ProveedorId=@prov AND pp.Activo=1 WHERE p.ProductoId=@prod AND p.Activo=1`);if(!vr.recordset[0])return res.status(400).json({ok:false,message:'Uno de los productos no pertenece al proveedor seleccionado.'});d.CostoUnitario=Number(vr.recordset[0].PrecioCompra);d.ImpuestoPorcentaje=Number(vr.recordset[0].PorcentajeImpuesto);}const tvp=new sql.Table('dbo.CompraDetalleType');tvp.columns.add('ProductoId',sql.Int);tvp.columns.add('Cantidad',sql.Decimal(18,2));tvp.columns.add('CostoUnitario',sql.Decimal(18,2));tvp.columns.add('ImpuestoPorcentaje',sql.Decimal(9,4));tvp.columns.add('Descuento',sql.Decimal(18,2));for(const d of detalles)tvp.rows.add(d.ProductoId,d.Cantidad,d.CostoUnitario,d.ImpuestoPorcentaje||0,d.Descuento||0);const r=await p.request().input('ProveedorId',sql.Int,req.body.ProveedorId).input('NumeroFacturaProveedor',sql.NVarChar(80),req.body.NumeroFacturaProveedor).input('FormaPago',sql.NVarChar(50),req.body.FormaPago).input('UsuarioId',sql.Int,req.user.id).input('Detalles',tvp).execute('sp_ConfirmarCompra');await audit(req,{module:'COMPRAS',action:'CONFIRMAR_COMPRA',operation:'TRANSACTION',recordId:r.recordset?.[0]?.CompraId});res.json({ok:true,data:r.recordset?.[0],message:'Compra confirmada e inventario actualizado.'});}catch(e){next(e)}});
router.post('/ventas/confirmar',async(req,res,next)=>{try{
 if(!has(req,'VENTAS_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});
 const p=await getPool();
 const detalles=req.body.detalles||[];
 if(!req.body.VendedorId||!req.body.CajeroId||!detalles.length)return res.status(400).json({ok:false,message:'Seleccione vendedor, cajero y al menos un producto.'});
 if(req.body.ClienteId){const cli=(await p.request().input('id',sql.Int,req.body.ClienteId).query('SELECT ClienteId FROM Clientes WHERE ClienteId=@id AND Activo=1')).recordset[0];if(!cli)return res.status(400).json({ok:false,message:'El cliente seleccionado no está disponible.'});}
 const vend=(await p.request().input('id',sql.Int,req.body.VendedorId).query(`SELECT TOP 1 e.EmpleadoId FROM Empleados e JOIN Usuarios u ON u.UsuarioId=e.UsuarioId AND u.Activo=1 JOIN UsuarioRoles ur ON ur.UsuarioId=u.UsuarioId AND ur.Activo=1 JOIN Roles r ON r.RolId=ur.RolId AND r.Activo=1 JOIN RolPermisos rp ON rp.RolId=r.RolId JOIN Permisos pe ON pe.PermisoId=rp.PermisoId AND pe.Activo=1 WHERE e.EmpleadoId=@id AND e.EstadoLaboral=N'ACTIVO' AND pe.Codigo IN(N'VENTAS_REGISTRAR',N'ADMIN_TOTAL')`)).recordset[0];
 if(!vend)return res.status(400).json({ok:false,message:'El vendedor seleccionado no tiene permiso para registrar ventas.'});
 const caj=(await p.request().input('id',sql.Int,req.body.CajeroId).query(`SELECT TOP 1 e.EmpleadoId FROM Empleados e JOIN Usuarios u ON u.UsuarioId=e.UsuarioId AND u.Activo=1 JOIN UsuarioRoles ur ON ur.UsuarioId=u.UsuarioId AND ur.Activo=1 JOIN Roles r ON r.RolId=ur.RolId AND r.Activo=1 JOIN RolPermisos rp ON rp.RolId=r.RolId JOIN Permisos pe ON pe.PermisoId=rp.PermisoId AND pe.Activo=1 WHERE e.EmpleadoId=@id AND e.EstadoLaboral=N'ACTIVO' AND pe.Codigo IN(N'PAGOS_REGISTRAR',N'FACTURAS_REGISTRAR',N'ADMIN_TOTAL')`)).recordset[0];
 if(!caj)return res.status(400).json({ok:false,message:'El cajero seleccionado no tiene los permisos requeridos.'});
 for(const d of detalles){
   if(!d.ProductoId||Number(d.Cantidad)<=0)return res.status(400).json({ok:false,message:'Cada línea debe tener producto y una cantidad mayor que cero.'});
   const pr=(await p.request().input('id',sql.Int,d.ProductoId).query(`SELECT ProductoId,PrecioVenta,PorcentajeImpuesto,ExistenciaActual FROM Productos WHERE ProductoId=@id AND Activo=1`)).recordset[0];
   if(!pr)return res.status(400).json({ok:false,message:'Uno de los productos seleccionados no existe o está inactivo.'});
   d.PrecioUnitario=Number(pr.PrecioVenta);
   d.ImpuestoPorcentaje=Number(pr.PorcentajeImpuesto);
   d.Descuento=Math.max(0,Number(d.Descuento||0));
 }
 const cfg=(await p.request().query('SELECT TOP 1 LimiteDescuento FROM ConfiguracionGeneral ORDER BY ConfiguracionId DESC')).recordset[0];
 const limite=Number(cfg?.LimiteDescuento??10);
 const supera=detalles.some(d=>{const base=Number(d.Cantidad)*Number(d.PrecioUnitario);return base>0&&(Number(d.Descuento||0)/base*100)>limite});
 if(supera&&!has(req,'DESCUENTOS_SUPERIOR_LIMITE'))return res.status(403).json({ok:false,message:`El descuento supera el límite de ${limite}% y requiere autorización.`});
 const tvp=new sql.Table('dbo.VentaDetalleType');
 tvp.columns.add('ProductoId',sql.Int);tvp.columns.add('Cantidad',sql.Decimal(18,2));tvp.columns.add('PrecioUnitario',sql.Decimal(18,2));tvp.columns.add('ImpuestoPorcentaje',sql.Decimal(9,4));tvp.columns.add('Descuento',sql.Decimal(18,2));
 for(const d of detalles)tvp.rows.add(d.ProductoId,d.Cantidad,d.PrecioUnitario,d.ImpuestoPorcentaje||0,d.Descuento||0);
 const r=await p.request().input('ClienteId',sql.Int,req.body.ClienteId||null).input('VendedorId',sql.Int,req.body.VendedorId).input('CajeroId',sql.Int,req.body.CajeroId).input('FormaPago',sql.NVarChar(50),req.body.FormaPago).input('UsuarioId',sql.Int,req.user.id).input('PermitirNegativo',sql.Bit,has(req,'INVENTARIO_NEGATIVO')?1:0).input('Detalles',tvp).execute('sp_ConfirmarVenta');
 await audit(req,{module:'VENTAS',action:'CONFIRMAR_VENTA',operation:'TRANSACTION',recordId:r.recordset?.[0]?.VentaId});
 res.json({ok:true,data:r.recordset?.[0],message:'Venta confirmada e inventario rebajado. La venta quedó disponible en Facturación.'});
}catch(e){next(e)}});
router.post('/pagos',async(req,res,next)=>{try{
 if(!has(req,'PAGOS_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});
 const facturaId=Number(req.body.FacturaId);
 if(!facturaId)return res.status(400).json({ok:false,message:'Seleccione una factura.'});
 let pagos=[];
 if(Array.isArray(req.body.Pagos)&&req.body.Pagos.length){
   pagos=req.body.Pagos.map(x=>({FormaPagoId:Number(x.FormaPagoId),Monto:Number(x.Monto)}));
 }else{
   pagos=[{FormaPagoId:Number(req.body.FormaPagoId),Monto:Number(req.body.Monto)}];
 }
 if(pagos.some(x=>!x.FormaPagoId||!(x.Monto>0)))return res.status(400).json({ok:false,message:'Cada forma de pago debe tener un monto mayor que cero.'});
 const p=await getPool();
 const r=await p.request()
   .input('FacturaId',sql.Int,facturaId)
   .input('PagosJson',sql.NVarChar(sql.MAX),JSON.stringify(pagos))
   .input('UsuarioId',sql.Int,req.user.id)
   .input('Observaciones',sql.NVarChar(500),req.body.Observaciones||null)
   .execute('sp_RegistrarPagosFactura');
 const resumen=r.recordsets?.[1]?.[0]||r.recordset?.[0]||{};
 await audit(req,{module:'PAGOS',action:'REGISTRAR_PAGO',operation:'TRANSACTION',recordId:facturaId,after:{PagoCompleto:resumen.Estado==='PAGADA',SaldoPendiente:resumen.SaldoPendiente}});
 res.json({ok:true,data:{pagos:r.recordsets?.[0]||[],resumen},message:resumen.Estado==='PAGADA'?'Pago registrado. La factura quedó PAGADA.':'Pago registrado. La factura quedó PARCIALMENTE PAGADA.'});
}catch(e){next(e)}});
router.post('/ordenes/:id/estado',async(req,res,next)=>{try{if(!has(req,'ORDENES_MODIFICAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();await p.request().input('OrdenTrabajoId',sql.Int,req.params.id).input('EstadoNuevo',sql.NVarChar(40),req.body.Estado).input('UsuarioId',sql.Int,req.user.id).input('Observacion',sql.NVarChar(500),req.body.Observacion||'').execute('sp_CambiarEstadoOrden');await audit(req,{module:'ORDENES',action:'CAMBIO_ESTADO',operation:'UPDATE',recordId:req.params.id,after:{Estado:req.body.Estado}});res.json({ok:true,message:'Estado actualizado e historial guardado.'});}catch(e){next(e)}});
router.post('/cotizaciones/:id/aprobar',async(req,res,next)=>{try{if(!has(req,'COTIZACIONES_APROBAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();const estado=(await p.request().input('id',sql.Int,req.params.id).query('SELECT Estado FROM Cotizaciones WHERE CotizacionId=@id')).recordset[0];if(!estado)return res.status(404).json({ok:false,message:'Cotización no encontrada.'});if(estado.Estado!=='CONVERTIDA')return res.status(409).json({ok:false,message:'La cotización debe estar en estado Convertida en una orden de trabajo.'});const ids=JSON.stringify(req.body.ServiciosAprobados||[]);const prods=JSON.stringify(req.body.ProductosAprobados||[]);const r=await p.request().input('CotizacionId',sql.Int,req.params.id).input('UsuarioId',sql.Int,req.user.id).input('TipoAprobacion',sql.NVarChar(20),req.body.TipoAprobacion||'TOTAL').input('ServiciosJson',sql.NVarChar(sql.MAX),ids).input('ProductosJson',sql.NVarChar(sql.MAX),prods).execute('sp_AprobarCotizacionYCrearOrden');await audit(req,{module:'COTIZACIONES',action:'APROBAR_Y_CONVERTIR',operation:'TRANSACTION',recordId:req.params.id});res.json({ok:true,data:r.recordset?.[0],message:'Cotización aprobada y orden generada.'});}catch(e){next(e)}});
router.post('/facturas/generar',async(req,res,next)=>{try{
 if(!has(req,'FACTURAS_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso para emitir facturas.'});
 const tipo=String(req.body.Tipo||'').toUpperCase();const id=Number(req.body.OrigenId);if(!id)return res.status(400).json({ok:false,message:'Seleccione una orden o venta disponible.'});
 const p=await getPool();let r;
 if(tipo==='ORDEN')r=await p.request().input('OrdenTrabajoId',sql.Int,id).input('UsuarioId',sql.Int,req.user.id).execute('sp_FacturarOrden');
 else if(tipo==='VENTA')r=await p.request().input('VentaId',sql.Int,id).input('UsuarioId',sql.Int,req.user.id).execute('sp_FacturarVenta');
 else return res.status(400).json({ok:false,message:'Tipo de origen inválido.'});
 const data=r.recordset?.[0]||{};await audit(req,{module:'FACTURACION',action:tipo==='ORDEN'?'FACTURAR_ORDEN':'FACTURAR_VENTA',operation:'TRANSACTION',recordId:data.FacturaId,after:{tipo,origenId:id}});
 res.json({ok:true,data,message:`Factura generada correctamente desde ${tipo==='ORDEN'?'la orden de trabajo':'la venta'}.`});
}catch(e){next(e)}});

router.get('/facturas/:id/pdf',async(req,res,next)=>{try{if(!has(req,'FACTURAS_CONSULTAR'))return res.status(403).end();const p=await getPool();const h=(await p.request().input('id',sql.Int,req.params.id).query(`SELECT f.*,c.NombreRazonSocial,c.Identificacion,c.Correo,c.Telefono,cg.NombreTaller,cg.IdentificacionJuridica,cg.Direccion TallerDireccion,cg.Telefono TallerTelefono FROM Facturas f LEFT JOIN Clientes c ON c.ClienteId=f.ClienteId CROSS JOIN (SELECT TOP 1 * FROM ConfiguracionGeneral ORDER BY ConfiguracionId DESC) cg WHERE FacturaId=@id`)).recordset[0];if(!h)return res.status(404).end();const ds=(await p.request().input('id',sql.Int,req.params.id).query('SELECT Descripcion,Cantidad,PrecioUnitario,Impuesto,Descuento,TotalLinea FROM FacturaDetalles WHERE FacturaId=@id')).recordset;const gs=(await p.request().input('id',sql.Int,req.params.id).query(`SELECT g.TipoCobertura,g.FechaInicio,g.FechaVencimiento,g.Condiciones,g.Estado,p.Nombre Producto,s.Nombre Servicio FROM Garantias g LEFT JOIN Productos p ON p.ProductoId=g.ProductoId LEFT JOIN Servicios s ON s.ServicioId=g.ServicioId JOIN Facturas f ON f.FacturaId=@id WHERE (g.OrdenTrabajoId=f.OrdenTrabajoId AND f.OrdenTrabajoId IS NOT NULL) OR (g.VentaId=f.VentaId AND f.VentaId IS NOT NULL) ORDER BY g.GarantiaId`)).recordset;const esc=s=>String(s??'').replace(/[()\\]/g,' ');let lines=[h.NombreTaller||'TallerPro',`Factura: ${h.NumeroFactura}`,`Fecha: ${new Date(h.FechaHora).toLocaleString('es-CR')}`,`Cliente: ${h.NombreRazonSocial||'Consumidor final'}`,`Identificacion: ${h.Identificacion||''}`,'',...ds.map(d=>`${d.Descripcion} x${d.Cantidad}  CRC ${Number(d.TotalLinea).toFixed(2)}`),'',`Subtotal: CRC ${Number(h.Subtotal).toFixed(2)}`,`Impuestos: CRC ${Number(h.Impuestos).toFixed(2)}`,`Descuentos: CRC ${Number(h.Descuentos).toFixed(2)}`,`TOTAL: CRC ${Number(h.Total).toFixed(2)}`,`Estado: ${h.Estado}`];if(gs.length){lines.push('','GARANTIAS:');for(const g of gs){lines.push(`${g.TipoCobertura}: ${g.Producto||''}${g.Servicio?' / '+g.Servicio:''}`,`Vigencia: ${String(g.FechaInicio).slice(0,10)} a ${String(g.FechaVencimiento).slice(0,10)} - ${g.Estado}`);if(g.Condiciones)lines.push(`Condiciones: ${g.Condiciones}`)}}let content='BT /F1 11 Tf 50 760 Td ';for(const l of lines){content+=`(${esc(l)}) Tj 0 -16 Td `}content+='ET';const objs=[];objs[1]='<< /Type /Catalog /Pages 2 0 R >>';objs[2]='<< /Type /Pages /Kids [3 0 R] /Count 1 >>';objs[3]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>';objs[4]=`<< /Length ${Buffer.byteLength(content)} >>\nstream\n${content}\nendstream`;objs[5]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';let pdf='%PDF-1.4\n',offs=[0];for(let i=1;i<=5;i++){offs[i]=Buffer.byteLength(pdf);pdf+=`${i} 0 obj\n${objs[i]}\nendobj\n`}const xref=Buffer.byteLength(pdf);pdf+='xref\n0 6\n0000000000 65535 f \n';for(let i=1;i<=5;i++)pdf+=String(offs[i]).padStart(10,'0')+' 00000 n \n';pdf+=`trailer << /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`inline; filename="${h.NumeroFactura}.pdf"`);res.send(Buffer.from(pdf));}catch(e){next(e)}});

router.post('/diagnosticos/:id/cotizacion',async(req,res,next)=>{try{if(!has(req,'COTIZACIONES_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();const diag=(await p.request().input('id',sql.Int,req.params.id).query(`SELECT Estado FROM Diagnosticos WHERE DiagnosticoId=@id`)).recordset[0];if(!diag)return res.status(404).json({ok:false,message:'Diagnóstico no encontrado.'});if(diag.Estado!=='FINALIZADO')return res.status(409).json({ok:false,message:'Solo un diagnóstico en estado Finalizado puede pasar a cotización.'});const r=await p.request().input('DiagnosticoId',sql.Int,req.params.id).input('UsuarioId',sql.Int,req.user.id).execute('sp_GenerarCotizacionDesdeDiagnostico');await audit(req,{module:'COTIZACIONES',action:'GENERAR_DESDE_DIAGNOSTICO',operation:'TRANSACTION',recordId:r.recordset?.[0]?.CotizacionId});res.json({ok:true,data:r.recordset?.[0],message:'Cotización generada desde el diagnóstico.'});}catch(e){next(e)}});
router.post('/ordenes/:id/facturar',async(req,res,next)=>{try{if(!has(req,'FACTURAS_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();const r=await p.request().input('OrdenTrabajoId',sql.Int,req.params.id).input('UsuarioId',sql.Int,req.user.id).execute('sp_FacturarOrden');await audit(req,{module:'FACTURACION',action:'FACTURAR_ORDEN',operation:'TRANSACTION',recordId:r.recordset?.[0]?.FacturaId});res.json({ok:true,data:r.recordset?.[0],message:'Factura generada desde la orden.'});}catch(e){next(e)}});

async function validarRecepcion(pool,b){
 const own=(await pool.request().input('v',sql.Int,b.VehiculoId).input('c',sql.Int,b.ClienteId).query('SELECT KilometrajeActual FROM Vehiculos WHERE VehiculoId=@v AND ClienteId=@c AND Activo=1')).recordset[0];
 if(!own){const e=new Error('El vehículo seleccionado no pertenece al cliente indicado.');e.status=400;throw e;}
 if(!Number.isInteger(Number(b.KilometrajeIngreso))||Number(b.KilometrajeIngreso)<0){const e=new Error('El kilometraje debe ser un número entero válido.');e.status=400;throw e;}
 if(Number(b.KilometrajeIngreso)<Number(own.KilometrajeActual||0)){const e=new Error('El kilometraje de recepción no puede ser menor al kilometraje actual registrado del vehículo.');e.status=400;throw e;}
 if(!['NULO','POCO','INTERMEDIO','LLENO'].includes(b.NivelCombustible)){const e=new Error('Seleccione un nivel de combustible válido.');e.status=400;throw e;}
 const emp=(await pool.request().input('e',sql.Int,b.EmpleadoRecibeId).query(`SELECT 1 ok FROM Empleados e JOIN Usuarios u ON u.UsuarioId=e.UsuarioId AND u.Activo=1 WHERE e.EmpleadoId=@e AND e.EstadoLaboral=N'ACTIVO' AND EXISTS(SELECT 1 FROM UsuarioRoles ur JOIN Roles r ON r.RolId=ur.RolId AND r.Activo=1 JOIN RolPermisos rp ON rp.RolId=r.RolId JOIN Permisos pe ON pe.PermisoId=rp.PermisoId AND pe.Activo=1 WHERE ur.UsuarioId=u.UsuarioId AND ur.Activo=1 AND pe.Codigo IN('RECEPCIONES_REGISTRAR','ADMIN_TOTAL'))`)).recordset[0];
 if(!emp){const e=new Error('El empleado seleccionado no tiene autorización para registrar recepciones.');e.status=400;throw e;}
 if(!String(b.MotivoVisita||'').trim()){const e=new Error('El motivo de la visita es obligatorio.');e.status=400;throw e;}
}
router.get('/recepciones/:id',async(req,res,next)=>{try{if(!has(req,'RECEPCIONES_CONSULTAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();const r=(await p.request().input('id',sql.Int,req.params.id).query(`SELECT RecepcionId,ClienteId,VehiculoId,KilometrajeIngreso,NivelCombustible,MotivoVisita,ProblemaCliente,AccesoriosObjetos,DanosVisibles,EmpleadoRecibeId,Observaciones FROM Recepciones WHERE RecepcionId=@id`)).recordset[0];if(!r)return res.status(404).json({ok:false,message:'Recepción no encontrada.'});res.json({ok:true,data:r});}catch(e){next(e)}});
router.post('/recepciones',async(req,res,next)=>{let tx;try{if(!has(req,'RECEPCIONES_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();await validarRecepcion(p,req.body);tx=new sql.Transaction(p);await tx.begin();const r=await new sql.Request(tx).input('ClienteId',sql.Int,req.body.ClienteId).input('VehiculoId',sql.Int,req.body.VehiculoId).input('Kilometraje',sql.Int,req.body.KilometrajeIngreso).input('Combustible',sql.NVarChar(30),req.body.NivelCombustible).input('Motivo',sql.NVarChar(500),req.body.MotivoVisita.trim()).input('Problema',sql.NVarChar(1500),req.body.ProblemaCliente||null).input('Accesorios',sql.NVarChar(1000),req.body.AccesoriosObjetos||null).input('Danos',sql.NVarChar(1500),req.body.DanosVisibles||null).input('Empleado',sql.Int,req.body.EmpleadoRecibeId).input('Obs',sql.NVarChar(1500),req.body.Observaciones||null).query(`INSERT Recepciones(ClienteId,VehiculoId,KilometrajeIngreso,NivelCombustible,MotivoVisita,ProblemaCliente,AccesoriosObjetos,DanosVisibles,EmpleadoRecibeId,FechaEstimadaEntrega,Observaciones,Estado) OUTPUT INSERTED.RecepcionId VALUES(@ClienteId,@VehiculoId,@Kilometraje,@Combustible,@Motivo,@Problema,@Accesorios,@Danos,@Empleado,NULL,@Obs,N'RECIBIDA'); UPDATE Vehiculos SET KilometrajeActual=@Kilometraje WHERE VehiculoId=@VehiculoId;`);const id=r.recordset[0].RecepcionId;await tx.commit();await audit(req,{module:'RECEPCIONES',action:'REGISTRAR',operation:'INSERT',recordId:id,after:req.body});res.json({ok:true,id,message:'Recepción registrada. La entrega estimada se calculará después del diagnóstico.'});}catch(e){if(tx&&tx._aborted===false)try{await tx.rollback()}catch{}next(e)}});
router.put('/recepciones/:id',async(req,res,next)=>{let tx;try{if(!has(req,'RECEPCIONES_MODIFICAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();await validarRecepcion(p,req.body);const before=(await p.request().input('id',sql.Int,req.params.id).query('SELECT * FROM Recepciones WHERE RecepcionId=@id')).recordset[0];if(!before)return res.status(404).json({ok:false,message:'Recepción no encontrada.'});tx=new sql.Transaction(p);await tx.begin();await new sql.Request(tx).input('id',sql.Int,req.params.id).input('ClienteId',sql.Int,req.body.ClienteId).input('VehiculoId',sql.Int,req.body.VehiculoId).input('Kilometraje',sql.Int,req.body.KilometrajeIngreso).input('Combustible',sql.NVarChar(30),req.body.NivelCombustible).input('Motivo',sql.NVarChar(500),req.body.MotivoVisita.trim()).input('Problema',sql.NVarChar(1500),req.body.ProblemaCliente||null).input('Accesorios',sql.NVarChar(1000),req.body.AccesoriosObjetos||null).input('Danos',sql.NVarChar(1500),req.body.DanosVisibles||null).input('Empleado',sql.Int,req.body.EmpleadoRecibeId).input('Obs',sql.NVarChar(1500),req.body.Observaciones||null).query(`UPDATE Recepciones SET ClienteId=@ClienteId,VehiculoId=@VehiculoId,KilometrajeIngreso=@Kilometraje,NivelCombustible=@Combustible,MotivoVisita=@Motivo,ProblemaCliente=@Problema,AccesoriosObjetos=@Accesorios,DanosVisibles=@Danos,EmpleadoRecibeId=@Empleado,Observaciones=@Obs WHERE RecepcionId=@id; UPDATE Vehiculos SET KilometrajeActual=CASE WHEN KilometrajeActual<@Kilometraje THEN @Kilometraje ELSE KilometrajeActual END WHERE VehiculoId=@VehiculoId;`);await tx.commit();await audit(req,{module:'RECEPCIONES',action:'MODIFICAR',operation:'UPDATE',recordId:req.params.id,before,after:req.body});res.json({ok:true,message:'Recepción actualizada.'});}catch(e){if(tx&&tx._aborted===false)try{await tx.rollback()}catch{}next(e)}});

