router.get('/diagnosticos/:id',async(req,res,next)=>{try{if(!has(req,'DIAGNOSTICOS_CONSULTAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();const r=await p.request().input('id',sql.Int,req.params.id).query('SELECT DiagnosticoId,RecepcionId,ProblemasEncontrados,PruebasRealizadas,PosiblesCausas,Recomendaciones,ManoObraEstimada,TiempoEstimadoMinutos,CostoEstimado,MecanicoResponsableId,Estado FROM Diagnosticos WHERE DiagnosticoId=@id');const d=r.recordset[0];if(!d)return res.status(404).json({ok:false,message:'Diagnóstico no encontrado.'});res.json({ok:true,data:d});}catch(e){next(e)}});
async function validarMecanicoDiagnostico(pool,recepcionId,mecanicoId){const r=await pool.request().input('rid',sql.Int,recepcionId).input('mid',sql.Int,mecanicoId).query(`DECLARE @veh INT,@ing DATETIME2;SELECT @veh=VehiculoId,@ing=FechaHoraIngreso FROM Recepciones WHERE RecepcionId=@rid;DECLARE @cita INT;SELECT TOP 1 @cita=c.CitaId FROM Citas c WHERE c.VehiculoId=@veh AND c.FechaHoraInicio<=DATEADD(DAY,1,@ing) ORDER BY ABS(DATEDIFF(MINUTE,c.FechaHoraInicio,@ing));SELECT 1 ok FROM CitaMecanicos WHERE CitaId=@cita AND EmpleadoId=@mid;`);return !!r.recordset[0];}
router.post('/diagnosticos',async(req,res,next)=>{try{if(!has(req,'DIAGNOSTICOS_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();if(!await validarMecanicoDiagnostico(p,req.body.RecepcionId,req.body.MecanicoResponsableId))return res.status(400).json({ok:false,message:'El mecánico responsable debe ser uno de los mecánicos asignados en la cita de este vehículo.'});const exists=(await p.request().input('r',sql.Int,req.body.RecepcionId).query('SELECT 1 ok FROM Diagnosticos WHERE RecepcionId=@r')).recordset[0];if(exists)return res.status(409).json({ok:false,message:'Ya existe un diagnóstico para esta recepción.'});const r=await p.request().input('RecepcionId',sql.Int,req.body.RecepcionId).input('Problemas',sql.NVarChar(2000),req.body.ProblemasEncontrados||null).input('Pruebas',sql.NVarChar(2000),req.body.PruebasRealizadas||null).input('Causas',sql.NVarChar(2000),req.body.PosiblesCausas||null).input('Rec',sql.NVarChar(2000),req.body.Recomendaciones||null).input('MO',sql.Decimal(18,2),req.body.ManoObraEstimada||0).input('Min',sql.Int,req.body.TiempoEstimadoMinutos||0).input('Costo',sql.Decimal(18,2),req.body.CostoEstimado||0).input('Mec',sql.Int,req.body.MecanicoResponsableId).input('Estado',sql.NVarChar(30),req.body.Estado||'PENDIENTE').query(`INSERT Diagnosticos(RecepcionId,ProblemasEncontrados,PruebasRealizadas,PosiblesCausas,Recomendaciones,ManoObraEstimada,TiempoEstimadoMinutos,CostoEstimado,MecanicoResponsableId,Estado) OUTPUT INSERTED.DiagnosticoId VALUES(@RecepcionId,@Problemas,@Pruebas,@Causas,@Rec,@MO,@Min,@Costo,@Mec,@Estado)`);const id=r.recordset[0].DiagnosticoId;await p.request().input('d',sql.Int,id).input('m',sql.Int,req.body.MecanicoResponsableId).query('INSERT DiagnosticoMecanicos(DiagnosticoId,EmpleadoId) VALUES(@d,@m)');await audit(req,{module:'DIAGNOSTICOS',action:'REGISTRAR',operation:'INSERT',recordId:id,after:req.body});res.json({ok:true,id,message:'Diagnóstico registrado.'});}catch(e){next(e)}});
router.put('/diagnosticos/:id',async(req,res,next)=>{try{if(!has(req,'DIAGNOSTICOS_MODIFICAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();if(!await validarMecanicoDiagnostico(p,req.body.RecepcionId,req.body.MecanicoResponsableId))return res.status(400).json({ok:false,message:'El mecánico responsable debe ser uno de los mecánicos asignados en la cita de este vehículo.'});await p.request().input('id',sql.Int,req.params.id).input('RecepcionId',sql.Int,req.body.RecepcionId).input('Problemas',sql.NVarChar(2000),req.body.ProblemasEncontrados||null).input('Pruebas',sql.NVarChar(2000),req.body.PruebasRealizadas||null).input('Causas',sql.NVarChar(2000),req.body.PosiblesCausas||null).input('Rec',sql.NVarChar(2000),req.body.Recomendaciones||null).input('MO',sql.Decimal(18,2),req.body.ManoObraEstimada||0).input('Min',sql.Int,req.body.TiempoEstimadoMinutos||0).input('Costo',sql.Decimal(18,2),req.body.CostoEstimado||0).input('Mec',sql.Int,req.body.MecanicoResponsableId).input('Estado',sql.NVarChar(30),req.body.Estado).query(`UPDATE Diagnosticos SET RecepcionId=@RecepcionId,ProblemasEncontrados=@Problemas,PruebasRealizadas=@Pruebas,PosiblesCausas=@Causas,Recomendaciones=@Rec,ManoObraEstimada=@MO,TiempoEstimadoMinutos=@Min,CostoEstimado=@Costo,MecanicoResponsableId=@Mec,Estado=@Estado WHERE DiagnosticoId=@id;IF NOT EXISTS(SELECT 1 FROM DiagnosticoMecanicos WHERE DiagnosticoId=@id AND EmpleadoId=@Mec) INSERT DiagnosticoMecanicos(DiagnosticoId,EmpleadoId) VALUES(@id,@Mec);`);await audit(req,{module:'DIAGNOSTICOS',action:'MODIFICAR',operation:'UPDATE',recordId:req.params.id,after:req.body});res.json({ok:true,message:'Diagnóstico actualizado.'});}catch(e){next(e)}});

