async function validarCita(pool,{CitaId=null,ClienteId,VehiculoId,AreaTrabajoId,FechaHoraInicio,ServicioIds,MecanicoIds}){
 const own=await pool.request().input('v',sql.Int,VehiculoId).input('c',sql.Int,ClienteId).query('SELECT 1 ok FROM Vehiculos WHERE VehiculoId=@v AND ClienteId=@c AND Activo=1');
 if(!own.recordset[0]){const e=new Error('El vehículo seleccionado no pertenece al cliente indicado.');e.status=400;throw e;}
 if(!Array.isArray(ServicioIds)||!ServicioIds.length){const e=new Error('Debe seleccionar al menos un servicio.');e.status=400;throw e;}
 if(!Array.isArray(MecanicoIds)||!MecanicoIds.length){const e=new Error('Debe seleccionar al menos un mecánico.');e.status=400;throw e;}
 const mins=(await pool.request().input('ids',sql.NVarChar(sql.MAX),JSON.stringify(ServicioIds)).query(`SELECT SUM(s.TiempoEstimadoMinutos) Minutos,COUNT(*) Cantidad FROM Servicios s JOIN OPENJSON(@ids) j ON s.ServicioId=TRY_CONVERT(int,j.value) WHERE s.Activo=1`)).recordset[0];
 if(Number(mins.Cantidad)!==ServicioIds.length){const e=new Error('Uno o más servicios seleccionados no son válidos o están inactivos.');e.status=400;throw e;}
 const dur=Number(mins.Minutos||0); const fin=new Date(new Date(FechaHoraInicio).getTime()+dur*60000);
 const req=pool.request().input('id',sql.Int,CitaId||0).input('inicio',sql.DateTime2,new Date(FechaHoraInicio)).input('fin',sql.DateTime2,fin).input('area',sql.Int,AreaTrabajoId).input('mecs',sql.NVarChar(sql.MAX),JSON.stringify(MecanicoIds));
 const col=(await req.query(`SELECT TOP 1 c.CitaId FROM Citas c WHERE c.CitaId<>@id AND c.Estado NOT IN(N'CANCELADA',N'CLIENTE AUSENTE') AND c.FechaHoraInicio<@fin AND DATEADD(minute,c.DuracionEstimadaMinutos,c.FechaHoraInicio)>@inicio AND (c.AreaTrabajoId=@area OR EXISTS(SELECT 1 FROM CitaMecanicos cm JOIN OPENJSON(@mecs) j ON cm.EmpleadoId=TRY_CONVERT(int,j.value) WHERE cm.CitaId=c.CitaId))`)).recordset[0];
 if(col){const e=new Error('Existe otra cita incompatible en ese horario para el área o alguno de los mecánicos seleccionados.');e.status=409;throw e;}
 return dur;
}
router.get('/citas/:id',async(req,res,next)=>{try{if(!has(req,'CITAS_CONSULTAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();const h=(await p.request().input('id',sql.Int,req.params.id).query('SELECT CitaId,ClienteId,VehiculoId,AreaTrabajoId,FechaHoraInicio,DuracionEstimadaMinutos,Observaciones FROM Citas WHERE CitaId=@id')).recordset[0];if(!h)return res.status(404).json({ok:false,message:'Cita no encontrada.'});h.ServicioIds=(await p.request().input('id',sql.Int,req.params.id).query('SELECT ServicioId FROM CitaServicios WHERE CitaId=@id')).recordset.map(x=>x.ServicioId);h.MecanicoIds=(await p.request().input('id',sql.Int,req.params.id).query('SELECT EmpleadoId FROM CitaMecanicos WHERE CitaId=@id')).recordset.map(x=>x.EmpleadoId);res.json({ok:true,data:h});}catch(e){next(e)}});
router.post('/citas',async(req,res,next)=>{let tx;try{if(!has(req,'CITAS_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();const dur=await validarCita(p,req.body);tx=new sql.Transaction(p);await tx.begin();const firstS=Number(req.body.ServicioIds[0]),firstM=Number(req.body.MecanicoIds[0]);const area=(await new sql.Request(tx).input('a',sql.Int,req.body.AreaTrabajoId).query('SELECT Nombre FROM AreasTrabajo WHERE AreaTrabajoId=@a AND Activa=1')).recordset[0];if(!area)throw new Error('Área de trabajo inválida.');const r=await new sql.Request(tx).input('ClienteId',sql.Int,req.body.ClienteId).input('VehiculoId',sql.Int,req.body.VehiculoId).input('ServicioId',sql.Int,firstS).input('EmpleadoId',sql.Int,firstM).input('AreaTrabajo',sql.NVarChar(100),area.Nombre).input('AreaTrabajoId',sql.Int,req.body.AreaTrabajoId).input('FechaHoraInicio',sql.DateTime2,new Date(req.body.FechaHoraInicio)).input('Duracion',sql.Int,dur).input('Observaciones',sql.NVarChar(1000),req.body.Observaciones||null).input('UsuarioId',sql.Int,req.user.id).query(`INSERT Citas(ClienteId,VehiculoId,ServicioId,EmpleadoId,AreaTrabajo,AreaTrabajoId,FechaHoraInicio,DuracionEstimadaMinutos,Estado,Observaciones,CreadaPorUsuarioId) OUTPUT INSERTED.CitaId VALUES(@ClienteId,@VehiculoId,@ServicioId,@EmpleadoId,@AreaTrabajo,@AreaTrabajoId,@FechaHoraInicio,@Duracion,N'PROGRAMADA',@Observaciones,@UsuarioId)`);const id=r.recordset[0].CitaId;for(const sid of req.body.ServicioIds)await new sql.Request(tx).input('c',sql.Int,id).input('s',sql.Int,sid).query('INSERT CitaServicios(CitaId,ServicioId) VALUES(@c,@s)');for(const mid of req.body.MecanicoIds)await new sql.Request(tx).input('c',sql.Int,id).input('m',sql.Int,mid).query('INSERT CitaMecanicos(CitaId,EmpleadoId) VALUES(@c,@m)');await tx.commit();await audit(req,{module:'CITAS',action:'REGISTRAR',operation:'INSERT',recordId:id,after:req.body});res.json({ok:true,id,message:'Cita registrada. Duración calculada automáticamente en '+dur+' minutos.'});}catch(e){if(tx&&tx._aborted===false)try{await tx.rollback()}catch{}next(e)}});
router.put('/citas/:id',async(req,res,next)=>{let tx;try{if(!has(req,'CITAS_MODIFICAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();const dur=await validarCita(p,{...req.body,CitaId:Number(req.params.id)});tx=new sql.Transaction(p);await tx.begin();const firstS=Number(req.body.ServicioIds[0]),firstM=Number(req.body.MecanicoIds[0]);const area=(await new sql.Request(tx).input('a',sql.Int,req.body.AreaTrabajoId).query('SELECT Nombre FROM AreasTrabajo WHERE AreaTrabajoId=@a AND Activa=1')).recordset[0];if(!area)throw new Error('Área de trabajo inválida.');await new sql.Request(tx).input('id',sql.Int,req.params.id).input('ClienteId',sql.Int,req.body.ClienteId).input('VehiculoId',sql.Int,req.body.VehiculoId).input('ServicioId',sql.Int,firstS).input('EmpleadoId',sql.Int,firstM).input('AreaTrabajo',sql.NVarChar(100),area.Nombre).input('AreaTrabajoId',sql.Int,req.body.AreaTrabajoId).input('FechaHoraInicio',sql.DateTime2,new Date(req.body.FechaHoraInicio)).input('Duracion',sql.Int,dur).input('Observaciones',sql.NVarChar(1000),req.body.Observaciones||null).query(`UPDATE Citas SET ClienteId=@ClienteId,VehiculoId=@VehiculoId,ServicioId=@ServicioId,EmpleadoId=@EmpleadoId,AreaTrabajo=@AreaTrabajo,AreaTrabajoId=@AreaTrabajoId,FechaHoraInicio=@FechaHoraInicio,DuracionEstimadaMinutos=@Duracion,Observaciones=@Observaciones WHERE CitaId=@id;DELETE CitaServicios WHERE CitaId=@id;DELETE CitaMecanicos WHERE CitaId=@id;`);for(const sid of req.body.ServicioIds)await new sql.Request(tx).input('c',sql.Int,req.params.id).input('s',sql.Int,sid).query('INSERT CitaServicios(CitaId,ServicioId) VALUES(@c,@s)');for(const mid of req.body.MecanicoIds)await new sql.Request(tx).input('c',sql.Int,req.params.id).input('m',sql.Int,mid).query('INSERT CitaMecanicos(CitaId,EmpleadoId) VALUES(@c,@m)');await tx.commit();await audit(req,{module:'CITAS',action:'MODIFICAR',operation:'UPDATE',recordId:req.params.id,after:req.body});res.json({ok:true,message:'Cita actualizada. Duración recalculada en '+dur+' minutos.'});}catch(e){if(tx&&tx._aborted===false)try{await tx.rollback()}catch{}next(e)}});


const ESTADOS_COTIZACION=new Set(['ENVIADA','APROBADA','APROBADA PARCIAL','RECHAZADA','MODIFICADA','CONVERTIDA']);
const DESCUENTOS_COTIZACION=new Set([0,5,10,15]);
async function datosDiagnosticoCotizacion(request,diagnosticoId){
 const r=await request.input('diag',sql.Int,diagnosticoId).query(`SELECT d.DiagnosticoId,d.Estado,d.TiempoEstimadoMinutos,d.CostoEstimado FROM Diagnosticos d WHERE d.DiagnosticoId=@diag`);
 return r.recordset[0];
}
async function recalcularCotizacion(request,cotizacionId,precioHora,descuentoPct){
 const rs=await request.input('cot',sql.Int,cotizacionId).query(`SELECT q.DiagnosticoId,d.TiempoEstimadoMinutos,d.CostoEstimado FROM Cotizaciones q JOIN Diagnosticos d ON d.DiagnosticoId=q.DiagnosticoId WHERE q.CotizacionId=@cot;SELECT ISNULL(SUM((Cantidad*PrecioUnitario)-Descuento),0) Base,ISNULL(SUM(((Cantidad*PrecioUnitario)-Descuento)*ImpuestoPorcentaje/100.0),0) Imp FROM CotizacionServicios WHERE CotizacionId=@cot;SELECT ISNULL(SUM((Cantidad*PrecioUnitario)-Descuento),0) Base,ISNULL(SUM(((Cantidad*PrecioUnitario)-Descuento)*ImpuestoPorcentaje/100.0),0) Imp FROM CotizacionProductos WHERE CotizacionId=@cot;`);
 const d=rs.recordsets[0][0];if(!d)throw new Error('Cotización no encontrada.');
 const horas=Number(d.TiempoEstimadoMinutos||0)/60;const montoMO=horas*Number(precioHora||0);const baseItems=Number(rs.recordsets[1][0]?.Base||0)+Number(rs.recordsets[2][0]?.Base||0);const impuestos=Number(rs.recordsets[1][0]?.Imp||0)+Number(rs.recordsets[2][0]?.Imp||0);const subtotal=Number(d.CostoEstimado||0)+montoMO+baseItems;const descuento=subtotal*Number(descuentoPct||0)/100;const total=subtotal+impuestos-descuento;
 return {horas,montoMO,subtotal,impuestos,descuento,total,costoDiagnostico:Number(d.CostoEstimado||0)};
}
router.get('/cotizaciones/:id',async(req,res,next)=>{try{if(!has(req,'COTIZACIONES_CONSULTAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const p=await getPool();const r=await p.request().input('id',sql.Int,req.params.id).query(`SELECT q.*,d.CostoEstimado CostoDiagnostico,c.NombreRazonSocial Cliente,v.Placa+N' — '+ma.Nombre+N' '+mo.Nombre Vehiculo FROM Cotizaciones q JOIN Diagnosticos d ON d.DiagnosticoId=q.DiagnosticoId JOIN Recepciones r ON r.RecepcionId=d.RecepcionId JOIN Clientes c ON c.ClienteId=r.ClienteId JOIN Vehiculos v ON v.VehiculoId=r.VehiculoId JOIN ModelosVehiculo mo ON mo.ModeloId=v.ModeloId JOIN MarcasVehiculo ma ON ma.MarcaId=mo.MarcaId WHERE q.CotizacionId=@id`);if(!r.recordset[0])return res.status(404).json({ok:false,message:'Cotización no encontrada.'});res.json({ok:true,data:r.recordset[0]});}catch(e){next(e)}});
router.post('/cotizaciones',async(req,res,next)=>{let tx;try{if(!has(req,'COTIZACIONES_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const estado=String(req.body.Estado||'').toUpperCase();const pct=Number(req.body.DescuentoPorcentaje||0);if(!ESTADOS_COTIZACION.has(estado))return res.status(400).json({ok:false,message:'Estado de cotización inválido.'});if(!DESCUENTOS_COTIZACION.has(pct))return res.status(400).json({ok:false,message:'El descuento permitido es 0%, 5%, 10% o 15%.'});if(!req.body.FechaVencimiento)return res.status(400).json({ok:false,message:'Indique la fecha de vencimiento.'});const precio=Number(req.body.PrecioHoraManoObra||0);if(precio<0)return res.status(400).json({ok:false,message:'Precio por hora inválido.'});const p=await getPool();const diag=await datosDiagnosticoCotizacion(p.request(),Number(req.body.DiagnosticoId));if(!diag)return res.status(404).json({ok:false,message:'Diagnóstico no encontrado.'});if(diag.Estado!=='FINALIZADO')return res.status(409).json({ok:false,message:'Solo un diagnóstico Finalizado puede pasar a cotización.'});if((await p.request().input('d',sql.Int,req.body.DiagnosticoId).query('SELECT 1 ok FROM Cotizaciones WHERE DiagnosticoId=@d')).recordset[0])return res.status(409).json({ok:false,message:'Ese diagnóstico ya tiene una cotización.'});tx=new sql.Transaction(p);await tx.begin();const r=await new sql.Request(tx).input('d',sql.Int,req.body.DiagnosticoId).input('vence',sql.Date,req.body.FechaVencimiento).input('precio',sql.Decimal(18,2),precio).input('pct',sql.Decimal(9,4),pct).input('cond',sql.NVarChar(1000),req.body.Condiciones||null).input('obs',sql.NVarChar(1000),req.body.Observaciones||null).input('estado',sql.NVarChar(30),estado).input('uid',sql.Int,req.user.id).query(`INSERT Cotizaciones(DiagnosticoId,FechaVencimiento,HorasManoObra,PrecioHoraManoObra,DescuentoPorcentaje,Condiciones,Observaciones,Estado,AprobacionTipo,UsuarioDecisionId,FechaHoraDecision) OUTPUT INSERTED.CotizacionId VALUES(@d,@vence,0,@precio,@pct,@cond,@obs,@estado,CASE WHEN @estado=N'APROBADA PARCIAL' THEN N'PARCIAL' WHEN @estado IN(N'APROBADA',N'CONVERTIDA') THEN N'TOTAL' ELSE NULL END,CASE WHEN @estado IN(N'APROBADA',N'APROBADA PARCIAL',N'RECHAZADA') THEN @uid ELSE NULL END,CASE WHEN @estado IN(N'APROBADA',N'APROBADA PARCIAL',N'RECHAZADA') THEN SYSDATETIME() ELSE NULL END)`);const id=r.recordset[0].CotizacionId;await new sql.Request(tx).input('id',sql.Int,id).input('d',sql.Int,req.body.DiagnosticoId).query(`INSERT CotizacionServicios(CotizacionId,ServicioId,Cantidad,PrecioUnitario,ImpuestoPorcentaje,TiempoEstimadoMinutos,Aprobado) SELECT @id,ds.ServicioId,ds.Cantidad,ds.PrecioEstimado,s.PorcentajeImpuesto,ds.TiempoEstimadoMinutos,CASE WHEN EXISTS(SELECT 1 FROM Cotizaciones q WHERE q.CotizacionId=@id AND q.Estado=N'APROBADA') THEN 1 ELSE NULL END FROM DiagnosticoServicios ds JOIN Servicios s ON s.ServicioId=ds.ServicioId WHERE ds.DiagnosticoId=@d AND ds.Recomendado=1;INSERT CotizacionProductos(CotizacionId,ProductoId,Cantidad,PrecioUnitario,ImpuestoPorcentaje,Aprobado) SELECT @id,dp.ProductoId,dp.Cantidad,dp.PrecioUnitarioEstimado,p.PorcentajeImpuesto,CASE WHEN EXISTS(SELECT 1 FROM Cotizaciones q WHERE q.CotizacionId=@id AND q.Estado=N'APROBADA') THEN 1 ELSE NULL END FROM DiagnosticoProductos dp JOIN Productos p ON p.ProductoId=dp.ProductoId WHERE dp.DiagnosticoId=@d;`);if(estado==='APROBADA PARCIAL'){const sids=req.body.ServiciosAprobados||[],pids=req.body.ProductosAprobados||[];await new sql.Request(tx).input('id',sql.Int,id).input('sj',sql.NVarChar(sql.MAX),JSON.stringify(sids)).input('pj',sql.NVarChar(sql.MAX),JSON.stringify(pids)).query(`UPDATE CotizacionServicios SET Aprobado=CASE WHEN ServicioId IN(SELECT TRY_CONVERT(int,value) FROM OPENJSON(@sj)) THEN 1 ELSE 0 END WHERE CotizacionId=@id;UPDATE CotizacionProductos SET Aprobado=CASE WHEN ProductoId IN(SELECT TRY_CONVERT(int,value) FROM OPENJSON(@pj)) THEN 1 ELSE 0 END WHERE CotizacionId=@id;`);}const calc=await recalcularCotizacion(new sql.Request(tx),id,precio,pct);await new sql.Request(tx).input('id',sql.Int,id).input('h',sql.Decimal(9,2),calc.horas).input('sub',sql.Decimal(18,2),calc.subtotal).input('imp',sql.Decimal(18,2),calc.impuestos).input('des',sql.Decimal(18,2),calc.descuento).input('tot',sql.Decimal(18,2),calc.total).query('UPDATE Cotizaciones SET HorasManoObra=@h,Subtotal=@sub,Impuestos=@imp,Descuento=@des,TotalEstimado=@tot WHERE CotizacionId=@id');await tx.commit();await audit(req,{module:'COTIZACIONES',action:'REGISTRAR',operation:'INSERT',recordId:id,after:req.body});res.json({ok:true,id,message:'Cotización registrada y totales calculados desde el diagnóstico.'});}catch(e){if(tx)try{await tx.rollback()}catch{}next(e)}});
router.put('/cotizaciones/:id',async(req,res,next)=>{let tx;try{if(!has(req,'COTIZACIONES_MODIFICAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});const estado=String(req.body.Estado||'').toUpperCase();const pct=Number(req.body.DescuentoPorcentaje||0);if(!ESTADOS_COTIZACION.has(estado)||!DESCUENTOS_COTIZACION.has(pct))return res.status(400).json({ok:false,message:'Estado o descuento inválido.'});const p=await getPool();const actual=(await p.request().input('id',sql.Int,req.params.id).query('SELECT * FROM Cotizaciones WHERE CotizacionId=@id')).recordset[0];if(!actual)return res.status(404).json({ok:false,message:'Cotización no encontrada.'});if((await p.request().input('id',sql.Int,req.params.id).query('SELECT 1 ok FROM OrdenesTrabajo WHERE CotizacionId=@id')).recordset[0])return res.status(409).json({ok:false,message:'La cotización ya tiene una orden de trabajo y no puede modificarse.'});const precio=Number(req.body.PrecioHoraManoObra||0);tx=new sql.Transaction(p);await tx.begin();await new sql.Request(tx).input('id',sql.Int,req.params.id).input('vence',sql.Date,req.body.FechaVencimiento).input('precio',sql.Decimal(18,2),precio).input('pct',sql.Decimal(9,4),pct).input('cond',sql.NVarChar(1000),req.body.Condiciones||null).input('obs',sql.NVarChar(1000),req.body.Observaciones||null).input('estado',sql.NVarChar(30),estado).input('uid',sql.Int,req.user.id).query(`UPDATE Cotizaciones SET FechaVencimiento=@vence,PrecioHoraManoObra=@precio,DescuentoPorcentaje=@pct,Condiciones=@cond,Observaciones=@obs,Estado=@estado,AprobacionTipo=CASE WHEN @estado=N'APROBADA PARCIAL' THEN N'PARCIAL' WHEN @estado=N'APROBADA' THEN N'TOTAL' ELSE AprobacionTipo END,UsuarioDecisionId=CASE WHEN @estado IN(N'APROBADA',N'APROBADA PARCIAL',N'RECHAZADA') THEN @uid ELSE UsuarioDecisionId END,FechaHoraDecision=CASE WHEN @estado IN(N'APROBADA',N'APROBADA PARCIAL',N'RECHAZADA') THEN SYSDATETIME() ELSE FechaHoraDecision END WHERE CotizacionId=@id`);if(estado==='APROBADA'){await new sql.Request(tx).input('id',sql.Int,req.params.id).query('UPDATE CotizacionServicios SET Aprobado=1 WHERE CotizacionId=@id;UPDATE CotizacionProductos SET Aprobado=1 WHERE CotizacionId=@id;')}else if(estado==='APROBADA PARCIAL'){const sids=req.body.ServiciosAprobados||[],pids=req.body.ProductosAprobados||[];await new sql.Request(tx).input('id',sql.Int,req.params.id).input('sj',sql.NVarChar(sql.MAX),JSON.stringify(sids)).input('pj',sql.NVarChar(sql.MAX),JSON.stringify(pids)).query(`UPDATE CotizacionServicios SET Aprobado=CASE WHEN ServicioId IN(SELECT TRY_CONVERT(int,value) FROM OPENJSON(@sj)) THEN 1 ELSE 0 END WHERE CotizacionId=@id;UPDATE CotizacionProductos SET Aprobado=CASE WHEN ProductoId IN(SELECT TRY_CONVERT(int,value) FROM OPENJSON(@pj)) THEN 1 ELSE 0 END WHERE CotizacionId=@id;`);}const calc=await recalcularCotizacion(new sql.Request(tx),Number(req.params.id),precio,pct);await new sql.Request(tx).input('id',sql.Int,req.params.id).input('h',sql.Decimal(9,2),calc.horas).input('sub',sql.Decimal(18,2),calc.subtotal).input('imp',sql.Decimal(18,2),calc.impuestos).input('des',sql.Decimal(18,2),calc.descuento).input('tot',sql.Decimal(18,2),calc.total).query('UPDATE Cotizaciones SET HorasManoObra=@h,Subtotal=@sub,Impuestos=@imp,Descuento=@des,TotalEstimado=@tot WHERE CotizacionId=@id');await tx.commit();await audit(req,{module:'COTIZACIONES',action:'MODIFICAR',operation:'UPDATE',recordId:req.params.id,before:actual,after:req.body});res.json({ok:true,message:'Cotización actualizada.'});}catch(e){if(tx)try{await tx.rollback()}catch{}next(e)}});
router.post('/cotizaciones/:id/convertir',async(req,res,next)=>{try{if(!has(req,'COTIZACIONES_APROBAR')&&!has(req,'ORDENES_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso para convertir la cotización en orden.'});const p=await getPool();const q=(await p.request().input('id',sql.Int,req.params.id).query('SELECT Estado,AprobacionTipo FROM Cotizaciones WHERE CotizacionId=@id')).recordset[0];if(!q)return res.status(404).json({ok:false,message:'Cotización no encontrada.'});if(q.Estado!=='CONVERTIDA')return res.status(409).json({ok:false,message:'La cotización solo puede pasar a Órdenes de trabajo cuando su estado sea "Convertida en una orden de trabajo".'});if((await p.request().input('id',sql.Int,req.params.id).query('SELECT 1 ok FROM OrdenesTrabajo WHERE CotizacionId=@id')).recordset[0])return res.status(409).json({ok:false,message:'Esta cotización ya fue convertida en orden.'});const tipo=q.AprobacionTipo||'TOTAL';const sids=tipo==='PARCIAL'?(await p.request().input('id',sql.Int,req.params.id).query('SELECT CotizacionServicioId FROM CotizacionServicios WHERE CotizacionId=@id AND Aprobado=1')).recordset.map(x=>x.CotizacionServicioId):[];const pids=tipo==='PARCIAL'?(await p.request().input('id',sql.Int,req.params.id).query('SELECT CotizacionProductoId FROM CotizacionProductos WHERE CotizacionId=@id AND Aprobado=1')).recordset.map(x=>x.CotizacionProductoId):[];const r=await p.request().input('CotizacionId',sql.Int,req.params.id).input('UsuarioId',sql.Int,req.user.id).input('TipoAprobacion',sql.NVarChar(20),tipo).input('ServiciosJson',sql.NVarChar(sql.MAX),JSON.stringify(sids)).input('ProductosJson',sql.NVarChar(sql.MAX),JSON.stringify(pids)).execute('sp_AprobarCotizacionYCrearOrden');await audit(req,{module:'COTIZACIONES',action:'CONVERTIR_A_ORDEN',operation:'TRANSACTION',recordId:req.params.id});res.json({ok:true,data:r.recordset?.[0],message:'Orden de trabajo creada desde la cotización.'});}catch(e){next(e)}});


const ESTADOS_ORDEN=new Set(['REGISTRADA','PENDIENTE DE APROBACION','APROBADA','EN PROCESO','EN ESPERA DE REPUESTOS','SUSPENDIDA','FINALIZADA','FACTURADA','ENTREGADA','CANCELADA']);
const PRIORIDADES_ORDEN=new Set(['ALTA','MEDIA','BAJA']);
async function validarEstadoOrden(pool,id,estado){
 if(!ESTADOS_ORDEN.has(estado))throw Object.assign(new Error('Estado de orden inválido.'),{status:400});
 if(estado==='FACTURADA'){
   const f=(await pool.request().input('id',sql.Int,id).query(`SELECT TOP 1 Estado FROM Facturas WHERE OrdenTrabajoId=@id AND Estado<>N'ANULADA' ORDER BY FacturaId DESC`)).recordset[0];
   if(!f)throw Object.assign(new Error('La orden solo puede marcarse Facturada cuando exista una factura asociada.'),{status:409});
 }
 if(estado==='ENTREGADA'){
   const f=(await pool.request().input('id',sql.Int,id).query(`SELECT TOP 1 Estado FROM Facturas WHERE OrdenTrabajoId=@id AND Estado<>N'ANULADA' ORDER BY FacturaId DESC`)).recordset[0];
   if(!f||f.Estado!=='PAGADA')throw Object.assign(new Error('La orden solo puede marcarse Entregada cuando su factura esté pagada.'),{status:409});
 }
}
router.get('/ordenes/:id',async(req,res,next)=>{try{
 if(!has(req,'ORDENES_CONSULTAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});
 const p=await getPool();
 const r=(await p.request().input('id',sql.Int,req.params.id).query(`SELECT o.*,q.NumeroCotizacion,c.NombreRazonSocial Cliente,v.Placa,ma.Nombre+N' '+mo.Nombre MarcaModelo,v.Placa+N' — '+ma.Nombre+N' '+mo.Nombre Vehiculo FROM OrdenesTrabajo o LEFT JOIN Cotizaciones q ON q.CotizacionId=o.CotizacionId JOIN Clientes c ON c.ClienteId=o.ClienteId JOIN Vehiculos v ON v.VehiculoId=o.VehiculoId JOIN ModelosVehiculo mo ON mo.ModeloId=v.ModeloId JOIN MarcasVehiculo ma ON ma.MarcaId=mo.MarcaId WHERE o.OrdenTrabajoId=@id`)).recordset[0];
 if(!r)return res.status(404).json({ok:false,message:'Orden no encontrada.'});res.json({ok:true,data:r});
}catch(e){next(e)}});
router.post('/ordenes',async(req,res,next)=>{let tx;try{
 if(!has(req,'ORDENES_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});
 const prioridad=String(req.body.Prioridad||'MEDIA').toUpperCase(),estado=String(req.body.Estado||'REGISTRADA').toUpperCase();
 if(!PRIORIDADES_ORDEN.has(prioridad))return res.status(400).json({ok:false,message:'Prioridad inválida. Use Alta, Media o Baja.'});
 if(!ESTADOS_ORDEN.has(estado))return res.status(400).json({ok:false,message:'Estado de orden inválido.'});
 if(['FACTURADA','ENTREGADA'].includes(estado))return res.status(409).json({ok:false,message:'Una orden nueva no puede iniciar como Facturada o Entregada.'});
 if(!req.body.FechaEstimadaEntrega)return res.status(400).json({ok:false,message:'Indique la fecha estimada de entrega.'});
 const p=await getPool();
 const q=(await p.request().input('id',sql.Int,req.body.CotizacionId).query(`SELECT q.CotizacionId,q.Estado,q.AprobacionTipo,d.RecepcionId,r.ClienteId,r.VehiculoId FROM Cotizaciones q JOIN Diagnosticos d ON d.DiagnosticoId=q.DiagnosticoId JOIN Recepciones r ON r.RecepcionId=d.RecepcionId WHERE q.CotizacionId=@id`)).recordset[0];
 if(!q)return res.status(404).json({ok:false,message:'Cotización no encontrada.'});
 if(q.Estado!=='CONVERTIDA')return res.status(409).json({ok:false,message:'Solo una cotización en estado Convertida en una orden de trabajo puede generar una orden.'});
 if((await p.request().input('id',sql.Int,req.body.CotizacionId).query('SELECT 1 ok FROM OrdenesTrabajo WHERE CotizacionId=@id')).recordset[0])return res.status(409).json({ok:false,message:'La cotización ya tiene una orden de trabajo.'});
 tx=new sql.Transaction(p);await tx.begin();
 const rq=new sql.Request(tx);const ins=await rq.input('cot',sql.Int,q.CotizacionId).input('cli',sql.Int,q.ClienteId).input('veh',sql.Int,q.VehiculoId).input('fecha',sql.DateTime2,new Date(req.body.FechaEstimadaEntrega)).input('pri',sql.NVarChar(20),prioridad).input('est',sql.NVarChar(40),estado).input('obs',sql.NVarChar(1500),req.body.Observaciones||null).input('uid',sql.Int,req.user.id).query(`INSERT OrdenesTrabajo(CotizacionId,ClienteId,VehiculoId,FechaEstimadaEntrega,Prioridad,Estado,Observaciones,UsuarioCreadorId) OUTPUT INSERTED.OrdenTrabajoId,INSERTED.NumeroOrden VALUES(@cot,@cli,@veh,@fecha,@pri,@est,@obs,@uid)`);
 const oid=ins.recordset[0].OrdenTrabajoId;
 await new sql.Request(tx).input('oid',sql.Int,oid).input('cid',sql.Int,q.CotizacionId).input('par',sql.Bit,q.AprobacionTipo==='PARCIAL'?1:0).query(`INSERT OrdenServicios(OrdenTrabajoId,ServicioId,Cantidad,PrecioAplicado,ImpuestoPorcentaje,DescuentoAplicado,TiempoEstimadoMinutos) SELECT @oid,ServicioId,Cantidad,PrecioUnitario,ImpuestoPorcentaje,Descuento,TiempoEstimadoMinutos FROM CotizacionServicios WHERE CotizacionId=@cid AND (@par=0 OR Aprobado=1);INSERT OrdenProductos(OrdenTrabajoId,ProductoId,CantidadAutorizada,CostoAplicado,PrecioAplicado,ImpuestoPorcentaje,DescuentoAplicado) SELECT @oid,cp.ProductoId,cp.Cantidad,p.PrecioCompra,cp.PrecioUnitario,cp.ImpuestoPorcentaje,cp.Descuento FROM CotizacionProductos cp JOIN Productos p ON p.ProductoId=cp.ProductoId WHERE cp.CotizacionId=@cid AND (@par=0 OR cp.Aprobado=1);`);
 await new sql.Request(tx).input('oid',sql.Int,oid).input('est',sql.NVarChar(40),estado).input('uid',sql.Int,req.user.id).query(`INSERT OrdenHistorialEstados(OrdenTrabajoId,EstadoAnterior,EstadoNuevo,UsuarioId,Observacion) VALUES(@oid,NULL,@est,@uid,N'Orden creada desde cotización convertida.')`);
 await new sql.Request(tx).input('rid',sql.Int,q.RecepcionId).input('fecha',sql.DateTime2,new Date(req.body.FechaEstimadaEntrega)).query('UPDATE Recepciones SET FechaEstimadaEntrega=@fecha WHERE RecepcionId=@rid');
 await new sql.Request(tx).input('cid',sql.Int,q.CotizacionId).input('uid',sql.Int,req.user.id).query('UPDATE Cotizaciones SET UsuarioConversionId=COALESCE(UsuarioConversionId,@uid),FechaHoraConversion=COALESCE(FechaHoraConversion,SYSDATETIME()) WHERE CotizacionId=@cid');
 await tx.commit();await audit(req,{module:'ORDENES',action:'REGISTRAR_DESDE_COTIZACION',operation:'TRANSACTION',recordId:oid,after:req.body});res.json({ok:true,id:oid,data:ins.recordset[0],message:'Orden de trabajo creada desde la cotización.'});
}catch(e){if(tx)try{await tx.rollback()}catch{}next(e)}});
router.put('/ordenes/:id',async(req,res,next)=>{try{
 if(!has(req,'ORDENES_MODIFICAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});
 const p=await getPool();const actual=(await p.request().input('id',sql.Int,req.params.id).query('SELECT * FROM OrdenesTrabajo WHERE OrdenTrabajoId=@id')).recordset[0];if(!actual)return res.status(404).json({ok:false,message:'Orden no encontrada.'});
 if(['FINALIZADA','FACTURADA','ENTREGADA','CANCELADA'].includes(actual.Estado)&&!has(req,'ORDENES_MODIFICAR_FINALIZADA'))return res.status(403).json({ok:false,message:'La orden está cerrada y requiere autorización especial para modificarse.'});
 const prioridad=String(req.body.Prioridad||actual.Prioridad).toUpperCase(),estado=String(req.body.Estado||actual.Estado).toUpperCase();if(!PRIORIDADES_ORDEN.has(prioridad))return res.status(400).json({ok:false,message:'Prioridad inválida.'});await validarEstadoOrden(p,Number(req.params.id),estado);
 await p.request().input('id',sql.Int,req.params.id).input('fecha',sql.DateTime2,new Date(req.body.FechaEstimadaEntrega)).input('pri',sql.NVarChar(20),prioridad).input('obs',sql.NVarChar(1500),req.body.Observaciones||null).query('UPDATE OrdenesTrabajo SET FechaEstimadaEntrega=@fecha,Prioridad=@pri,Observaciones=@obs WHERE OrdenTrabajoId=@id');
 if(estado!==actual.Estado)await p.request().input('OrdenTrabajoId',sql.Int,req.params.id).input('EstadoNuevo',sql.NVarChar(40),estado).input('UsuarioId',sql.Int,req.user.id).input('Observacion',sql.NVarChar(500),req.body.Observaciones||'Cambio desde edición de orden.').execute('sp_CambiarEstadoOrden');
 await audit(req,{module:'ORDENES',action:'MODIFICAR',operation:'UPDATE',recordId:req.params.id,before:actual,after:req.body});res.json({ok:true,message:'Orden actualizada.'});
}catch(e){next(e)}});


router.post('/garantias',async(req,res,next)=>{try{
 if(!has(req,'GARANTIAS_REGISTRAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});
 const origen=String(req.body.OrigenTipo||'').toUpperCase(), origenId=Number(req.body.OrigenId), cobertura=String(req.body.TipoCobertura||'').toUpperCase();
 const productoId=Number(req.body.ProductoId), servicioId=req.body.ServicioId?Number(req.body.ServicioId):null;
 const estado=String(req.body.Estado||'ACTIVA').toUpperCase();
 if(!['ORDEN','VENTA'].includes(origen)||!origenId)return res.status(400).json({ok:false,message:'Seleccione una orden o venta válida.'});
 if(!['PRODUCTO','SERVICIO Y REPUESTO'].includes(cobertura))return res.status(400).json({ok:false,message:'Tipo de cobertura inválido.'});
 if(origen==='VENTA'&&cobertura!=='PRODUCTO')return res.status(400).json({ok:false,message:'Una venta directa solo puede generar garantía de PRODUCTO.'});
 if(!productoId)return res.status(400).json({ok:false,message:'Seleccione el producto o repuesto cubierto.'});
 if(cobertura==='SERVICIO Y REPUESTO'&&!servicioId)return res.status(400).json({ok:false,message:'Seleccione el servicio cubierto.'});
 if(!['ACTIVA','INACTIVA'].includes(estado))return res.status(400).json({ok:false,message:'Estado de garantía inválido.'});
 if(!req.body.FechaInicio||!req.body.FechaVencimiento||new Date(req.body.FechaVencimiento)<new Date(req.body.FechaInicio))return res.status(400).json({ok:false,message:'Las fechas de garantía son obligatorias y el vencimiento no puede ser anterior al inicio.'});
 const p=await getPool();
 let f;
 if(origen==='ORDEN')f=(await p.request().input('id',sql.Int,origenId).query(`SELECT TOP 1 FacturaId,NumeroFactura FROM Facturas WHERE OrdenTrabajoId=@id AND Estado=N'PAGADA' AND SaldoPendiente=0 ORDER BY FacturaId DESC`)).recordset[0];
 else f=(await p.request().input('id',sql.Int,origenId).query(`SELECT TOP 1 FacturaId,NumeroFactura FROM Facturas WHERE VentaId=@id AND Estado=N'PAGADA' AND SaldoPendiente=0 ORDER BY FacturaId DESC`)).recordset[0];
 if(!f)return res.status(409).json({ok:false,message:'Solo se puede registrar la garantía cuando la factura relacionada esté completamente PAGADA.'});
 const prod=(await p.request().input('fid',sql.Int,f.FacturaId).input('pid',sql.Int,productoId).query(`SELECT TOP 1 1 ok FROM FacturaDetalles WHERE FacturaId=@fid AND ProductoId=@pid`)).recordset[0];
 if(!prod)return res.status(400).json({ok:false,message:'El producto o repuesto seleccionado no pertenece a la factura pagada.'});
 if(servicioId){const serv=(await p.request().input('fid',sql.Int,f.FacturaId).input('sid',sql.Int,servicioId).query(`SELECT TOP 1 1 ok FROM FacturaDetalles WHERE FacturaId=@fid AND ServicioId=@sid`)).recordset[0];if(!serv)return res.status(400).json({ok:false,message:'El servicio seleccionado no pertenece a la factura pagada.'});}
 const dupReq=p.request().input('oid',sql.Int,origen==='ORDEN'?origenId:null).input('vid',sql.Int,origen==='VENTA'?origenId:null).input('pid',sql.Int,productoId).input('sid',sql.Int,servicioId);
 const dup=(await dupReq.query(`SELECT TOP 1 GarantiaId FROM Garantias WHERE ISNULL(OrdenTrabajoId,0)=ISNULL(@oid,0) AND ISNULL(VentaId,0)=ISNULL(@vid,0) AND ProductoId=@pid AND ISNULL(ServicioId,0)=ISNULL(@sid,0)`)).recordset[0];
 if(dup)return res.status(409).json({ok:false,message:'Ya existe una garantía para ese origen y elemento cubierto.'});
 const r=await p.request().input('oid',sql.Int,origen==='ORDEN'?origenId:null).input('vid',sql.Int,origen==='VENTA'?origenId:null).input('pid',sql.Int,productoId).input('sid',sql.Int,servicioId).input('tipo',sql.NVarChar(40),cobertura).input('fi',sql.Date,req.body.FechaInicio).input('fv',sql.Date,req.body.FechaVencimiento).input('cond',sql.NVarChar(1500),req.body.Condiciones||null).input('est',sql.NVarChar(30),estado).input('obs',sql.NVarChar(1000),req.body.Observaciones||null).query(`INSERT Garantias(OrdenTrabajoId,VentaId,ProductoId,ServicioId,TipoCobertura,FechaInicio,FechaVencimiento,Condiciones,Estado,Observaciones) OUTPUT INSERTED.GarantiaId VALUES(@oid,@vid,@pid,@sid,@tipo,@fi,@fv,@cond,@est,@obs)`);
 const gid=r.recordset[0].GarantiaId; await audit(req,{module:'GARANTIAS',action:'REGISTRAR',operation:'INSERT',recordId:gid,after:req.body});
 res.json({ok:true,id:gid,message:`Garantía registrada para la factura ${f.NumeroFactura}.`});
}catch(e){next(e)}});

router.patch('/garantias/:id/estado',async(req,res,next)=>{try{
 if(!has(req,'GARANTIAS_MODIFICAR')&&!has(req,'GARANTIAS_DESACTIVAR'))return res.status(403).json({ok:false,message:'Sin permiso.'});
 const estado=String(req.body.Estado||'').toUpperCase();if(!['ACTIVA','INACTIVA'].includes(estado))return res.status(400).json({ok:false,message:'Estado inválido.'});
 const p=await getPool();const before=(await p.request().input('id',sql.Int,req.params.id).query('SELECT * FROM Garantias WHERE GarantiaId=@id')).recordset[0];if(!before)return res.status(404).json({ok:false,message:'Garantía no encontrada.'});
 await p.request().input('id',sql.Int,req.params.id).input('e',sql.NVarChar(30),estado).query('UPDATE Garantias SET Estado=@e WHERE GarantiaId=@id');
 await audit(req,{module:'GARANTIAS',action:'CAMBIAR_ESTADO',operation:'UPDATE',recordId:req.params.id,before,after:{Estado:estado}});res.json({ok:true,message:'Estado de garantía actualizado.'});
}catch(e){next(e)}});

module.exports=router;
